with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos penales, el artículo 24 del Código Penal considera funcionario público a:', 'El art. 24.2 CP adopta un concepto funcional de funcionario; el mando o jurisdicción propia define la autoridad (24.1).', 'iipp_b07_delitos_administracion_publica', (select id from public.topics where slug = 'iipp-b07-delitos-administracion-publica'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 24.2 CP', 'Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas.', null, 'd00c7d80988c8e2bae699193bc2ab265906630e3cc2a8262ed962c26d862a8a6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd00c7d80988c8e2bae699193bc2ab265906630e3cc2a8262ed962c26d862a8a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo quien haya superado una oposición.', false), ('B', 'Solo el personal con nombramiento de carrera.', false), ('C', 'Quien tenga mando o ejerza jurisdicción propia.', false), ('D', 'Todo el que por disposición inmediata de la ley, por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas.', true)) as v(label, body, ok)
)
