insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c01-regulacion-supranacional' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Ley 23/2014, de reconocimiento mutuo de resoluciones penales en la Unión Europea, se basa en el principio por el que las autoridades judiciales españolas reconocen y ejecutan las resoluciones transmitidas por otro Estado miembro:', 'El art. 1 de la Ley 23/2014 impone el reconocimiento salvo motivo tasado de denegación.', 'iipp_c01_regulacion_supranacional', (select id from public.topics where slug = 'iipp-c01-regulacion-supranacional'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 1 Ley 23/2014', 'cuando hayan sido transmitidas correctamente por la autoridad competente de otro Estado miembro y no concurra ningún motivo tasado de denegación del reconocimiento o la ejecución.', null, 'aecfa5969c57197c47b0ec094edfd1624bb24dc62c6306644ca3d1690b343547', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'aecfa5969c57197c47b0ec094edfd1624bb24dc62c6306644ca3d1690b343547')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo si existe reciprocidad declarada por el Gobierno.', false), ('B', 'Previa revisión del fondo del asunto.', false), ('C', 'Solo si el delito está tipificado de forma idéntica en ambos Estados.', false), ('D', 'Cuando no concurra ningún motivo tasado de denegación del reconocimiento o la ejecución.', true)) as v(label, body, ok)
)
