  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una enfermería con número suficiente de camas.', false), ('B', 'Una dependencia destinada a la observación psiquiátrica y a la atención de los toxicómanos.', false), ('C', 'Una unidad para enfermos contagiosos.', false), ('D', 'Un quirófano para cirugía mayor.', true)) as v(label, body, ok)
)
