with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Señale la respuesta INCORRECTA sobre los criterios de separación interior del artículo 16 de la Ley Orgánica General Penitenciaria:', 'El art. 16 LOGP no recoge la nacionalidad como criterio de separación.', 'iipp_c09_tratamiento_clasificacion', (select id from public.topics where slug = 'iipp-c09-tratamiento-clasificacion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. dieciséis LOGP', 'b) Los detenidos y presos estarán separados de los condenados y, en ambos casos, los primarios de los reincidentes. c) Los jóvenes, sean detenidos, presos o penados, estarán separados de los adultos en las condiciones que se determinen reglamentariamente.', null, 'ab0770bd6562eca0aff9abfa35e1c75ecb7b8dec5bb1d3f8ce32be219cea0cdd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ab0770bd6562eca0aff9abfa35e1c75ecb7b8dec5bb1d3f8ce32be219cea0cdd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los internos preventivos estarán separados de los extranjeros.', true), ('B', 'Los detenidos y presos estarán separados de los condenados.', false), ('C', 'Los jóvenes estarán separados de los adultos en las condiciones que se determinen reglamentariamente.', false), ('D', 'Los detenidos y presos por delitos dolosos estarán separados de los que estén por delitos de imprudencia.', false)) as v(label, body, ok)
)
