with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes NO figura entre los órganos colegiados que el artículo 265 del Reglamento Penitenciario prevé en cada establecimiento?', 'El art. 265.1 RP enumera Consejo de Dirección, Junta de Tratamiento, Comisión Disciplinaria y Junta Económico-Administrativa. La Junta de Régimen y Administración era un órgano del Reglamento de 1981.', 'iipp_c17_modelo_organizativo', (select id from public.topics where slug = 'iipp-c17-modelo-organizativo'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 265.1 RP', 'En cada Establecimiento penitenciario existirán los siguientes órganos colegiados: a) Consejo de Dirección. b) Junta de Tratamiento, que tendrá a su disposición, como unidades de estudio, propuesta y ejecución, el Equipo o Equipos Técnicos necesarios. c) Comisión Disciplinaria. d) Junta Económico-Administrativa.', null, '57b88bd8f3d68ff0d18cfb779ccdff3020845ce94cdd9b5a2b3d615da00962fa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '57b88bd8f3d68ff0d18cfb779ccdff3020845ce94cdd9b5a2b3d615da00962fa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consejo de Dirección.', false), ('B', 'La Comisión Disciplinaria.', false), ('C', 'La Junta de Régimen y Administración.', true), ('D', 'La Junta Económico-Administrativa.', false)) as v(label, body, ok)
)
