  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Director podrá solicitar a la Autoridad judicial competente autorización para aplicar otros medios de control adecuados.', true), ('B', 'El Jefe de Servicios puede ordenar una exploración radiológica sin más trámite.', false), ('C', 'Debe repetirse el cacheo con desnudo integral cada doce horas.', false), ('D', 'El interno pasa automáticamente a régimen cerrado.', false)) as v(label, body, ok)
)
