  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Tras una requisa en el módulo 2 y varios cacheos, el funcionario debe documentar la actuación. Según el Reglamento Penitenciario, el parte escrito, que especificará los cacheos con desnudo integral efectuados, se dirige a:', 'El art. 68.5 RP dirige el parte al Jefe de Servicios.', 'iippsup_s1_regimen_seguridad', (select id from public.topics where slug = 'iippsup-s1-regimen-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.5 RP', 'se formulará parte escrito, que deberá especificar los cacheos con desnudo integral efectuados, firmado por los funcionarios que lo hayan efectuado y dirigido al Jefe de Servicios.', null, '0158ce89d83456bbfb520ce0feaf95644ac9fe84661ba82d24f4d4318e917c47', false
