  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Al penado Iván C. se le han impuesto limitaciones regimentales para proteger su vida, por amenazas de otros internos. Para que puedan levantarse, se plantea su traslado a otro centro de características similares. Según el Reglamento Penitenciario, ¿quién propone ese traslado al Centro Directivo?', 'El art. 75.3 RP: el Consejo de Dirección para detenidos y presos y la Junta de Tratamiento para penados.', 'iippsup_s1_regimen_seguridad', (select id from public.topics where slug = 'iippsup-s1-regimen-seguridad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 75.3 RP', 'el Consejo de Dirección, en el caso de los detenidos y presos, o la Junta de Tratamiento, en el caso de penados, propondrán al Centro Directivo el traslado del recluso', null, '112b5e7dba331e950d1baab4802bf1f521531a145725f1fbecb425472e558776', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '112b5e7dba331e950d1baab4802bf1f521531a145725f1fbecb425472e558776')
  returning id
), o as (
