  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Por falta de personal en el turno de noche, el Director del Centro de Peñalba asigna provisionalmente dos unidades de servicio a un solo funcionario. Según el Reglamento Penitenciario, esta facultad del Director:', 'El art. 280.2.4.ª e) RP atribuye esa facultad al Director.', 'iippsup_s3_disciplina_gestion', (select id from public.topics where slug = 'iippsup-s3-disciplina-gestion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 280.2.4.ª e) RP', 'en casos de necesidad, asignar provisionalmente dos o más unidades a un solo funcionario, teniendo en cuenta las necesidades de coordinación de los distintos puestos o unidades y las cargas reales de trabajo que tengan asignadas.', null, 'd293ce29125d87030df6dae37b48bffa15ea2fa9d027251412b0997000048fd7', false
