insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Poder Judicial: principios (art. 117 CE)"},{"n":"2","title":"El Consejo General del Poder Judicial (art. 122 CE)"},{"n":"3","title":"Organización jurisdiccional (art. 26 LOPJ)"},{"n":"4","title":"El Ministerio Fiscal (art. 124 CE)"},{"n":"5","title":"El Tribunal Constitucional: composición (arts. 159-160 CE)"},{"n":"6","title":"Competencias, legitimación y sentencias del TC (arts. 161-164 CE)"}]'::jsonb, '["Art. 117.1 CE: «La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial»","Art. 117.1 CE: «independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.»","Art. 117.2 CE: «Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados, sino por alguna de las causas y con las garantías previstas en la ley.»","Art. 117.3 CE: «corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes»","Art. 122.2 CE: «El Consejo General del Poder Judicial es el órgano de gobierno del mismo.»","Art. 122.3 CE: «y por veinte miembros nombrados por el Rey por un período de cinco años.»","Art. 122.3 CE: «De éstos, doce entre Jueces y Magistrados de todas las categorías judiciales»","Art. 124.1 CE: «tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley»","Art. 124.2 CE: «El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica»","Art. 124.4 CE: «El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial.»","Art. 159.1 CE: «El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey»","Art. 159.1 CE: «dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.»","Art. 159.2 CE: «todos ellos juristas de reconocida competencia con más de quince años de ejercicio profesional.»","Art. 160 CE: «a propuesta del mismo Tribunal en pleno y por un período de tres años.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, null
  from public.topics t where t.slug = 'iipp-a02-poder-judicial-tc-fiscal'
