insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a03-gobierno-periferica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Gobierno: funciones y composición (arts. 97-98 CE; art. 1 Ley 50/1997)"},{"n":"2","title":"Investidura y cese (arts. 99-101 CE)"},{"n":"3","title":"Responsabilidad política: cuestión de confianza y moción de censura (arts. 108-114 CE)"},{"n":"4","title":"Consejo de Ministros y Ministros (arts. 4-5 Ley 50/1997)"},{"n":"5","title":"Administración periférica: Delegados y Subdelegados del Gobierno (arts. 69-75 Ley 40/2015)"}]'::jsonb, '["Art. 97 CE: «Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.»","Art. 98.1 CE: «El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley.»","Art. 98.2 CE: «El Presidente dirige la acción del Gobierno y coordina las funciones de los demás miembros del mismo»","Art. 99.1 CE: «previa consulta con los representantes designados por los Grupos políticos con representación parlamentaria, y a través del Presidente del Congreso, propondrá un candidato a la Presidencia del Gobierno.»","Art. 101 CE: «El Gobierno cesante continuará en funciones hasta la toma de posesión del nuevo Gobierno.»","Art. 101 CE: «El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente.»","Art. 108 CE: «El Gobierno responde solidariamente en su gestión política ante el Congreso de los Diputados.»","Art. 112 CE: «La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados.»","Art. 113.2 CE: «La moción de censura deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno.»","Art. 113.3 CE: «La moción de censura no podrá ser votada hasta que transcurran cinco días desde su presentación.»","Art. 113.1 CE: «El Congreso de los Diputados puede exigir la responsabilidad política del Gobierno mediante la adopción por mayoría absoluta de la moción de censura.»","Art. 114.2 CE: «el candidato incluido en aquélla se entenderá investido de la confianza de la Cámara a los efectos previstos en el artículo 99. El Rey le nombrará Presidente del Gobierno.»","Art. 1.3 Ley 50/1997: «Los miembros del Gobierno se reúnen en Consejo de Ministros y en Comisiones Delegadas del Gobierno.»","Art. 5.1 Ley 50/1997: «c) Aprobar los Reales Decretos-leyes y los Reales Decretos Legislativos.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: Ley 50/1997 (https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336)'
  from public.topics t where t.slug = 'iipp-a03-gobierno-periferica'
