insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a04-organizacion-territorial' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Principios de la organización territorial (arts. 2 y 137 CE)"},{"n":"2","title":"Municipio y provincia (arts. 140-141 CE)"},{"n":"3","title":"Las Comunidades Autónomas y sus Estatutos (arts. 143-147 CE)"},{"n":"4","title":"Distribución de competencias (arts. 148-150 CE)"},{"n":"5","title":"Instituciones y control de las CCAA (arts. 152-155 CE)"},{"n":"6","title":"Competencias en materia penitenciaria (art. 149.1.6.ª CE y art. 79 LOGP)"}]'::jsonb, '["Art. 2 CE: «reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran y la solidaridad entre todas ellas.»","Art. 137 CE: «El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.»","Art. 140 CE: «Los Alcaldes serán elegidos por los Concejales o por los vecinos.»","Art. 141.1 CE: «Cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica.»","Art. 141.2 CE: «El gobierno y la administración autónoma de las provincias estarán encomendados a Diputaciones u otras Corporaciones de carácter representativo.»","Art. 145.1 CE: «En ningún caso se admitirá la federación de Comunidades Autónomas.»","Art. 147.1 CE: «los Estatutos serán la norma institucional básica de cada Comunidad Autónoma»","Art. 149.1.6.ª CE: «6.ª Legislación mercantil, penal y penitenciaria; legislación procesal»","Art. 149.1.2.ª CE: «2.ª Nacionalidad, inmigración, emigración, extranjería y derecho de asilo.»","Art. 149.3 CE: «El derecho estatal será, en todo caso, supletorio del derecho de las Comunidades Autónomas.»","Art. 149.3 CE: «Las materias no atribuidas expresamente al Estado por esta Constitución podrán corresponder a las Comunidades Autónomas, en virtud de sus respectivos Estatutos.»","Art. 150.2 CE: «El Estado podrá transferir o delegar en las Comunidades Autónomas, mediante ley orgánica, facultades correspondientes a materia de titularidad estatal»","Art. 152.1 CE: «la organización institucional autonómica se basará en una Asamblea Legislativa, elegida por sufragio universal, con arreglo a un sistema de representación proporcional»","Art. 153 CE: «c) Por la jurisdicción contencioso-administrativa, el de la administración autónoma y sus normas reglamentarias.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, null
  from public.topics t where t.slug = 'iipp-a04-organizacion-territorial'
