insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Instituciones de la Unión (art. 13 TUE)"},{"n":"2","title":"Parlamento Europeo (art. 14 TUE)"},{"n":"3","title":"Consejo Europeo (art. 15 TUE)"},{"n":"4","title":"Consejo (art. 16 TUE)"},{"n":"5","title":"Comisión y Alto Representante (arts. 17-18 TUE)"},{"n":"6","title":"Tribunal de Justicia (art. 19 TUE)"},{"n":"7","title":"Actos jurídicos de la Unión (art. 288 TFUE)"},{"n":"8","title":"Retirada de la Unión (art. 50 TUE)"}]'::jsonb, '["Art. 13.1 TUE: «El Tribunal de Justicia de la Unión Europea, El Banco Central Europeo, El Tribunal de Cuentas.»","Art. 13.4 TUE: «estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas.»","Art. 14.1 TUE: «El Parlamento Europeo ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria.»","Art. 14.2 TUE: «No se asignará a ningún Estado miembro más de noventa y seis escaños.»","Art. 14.3 TUE: «serán elegidos por sufragio universal directo, libre y secreto, para un mandato de cinco años.»","Art. 15.5 TUE: «El Consejo Europeo elegirá a su Presidente por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez.»","Art. 15.3 TUE: «El Consejo Europeo se reunirá dos veces por semestre por convocatoria de su Presidente.»","Art. 16.2 TUE: «El Consejo estará compuesto por un representante de cada Estado miembro, de rango ministerial»","Art. 16.4 TUE: «represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión.»","Art. 16.4 TUE: «Una minoría de bloqueo estará compuesta por al menos cuatro miembros del Consejo»","Art. 17.2 TUE: «Los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los Tratados dispongan otra cosa.»","Art. 17.8 TUE: «La Comisión tendrá una responsabilidad colegiada ante el Parlamento Europeo.»","Art. 18.3 TUE: «El Alto Representante presidirá el Consejo de Asuntos Exteriores.»","Art. 19.2 TUE: «El Tribunal de Justicia estará compuesto por un juez por Estado miembro. Estará asistido por abogados generales.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT', null, null, null, null
  from public.topics t where t.slug = 'iipp-a05-union-europea'
