insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 9/2017, de 8 de noviembre, de Contratos del Sector Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-a10-contratos-sector-publico', 'Primera parte, tema 10. Los contratos del sector público') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a10-contratos-sector-publico' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Objeto, principios y ámbito (arts. 1-2 LCSP)"},{"n":"2","title":"Tipos de contratos (arts. 12-17 LCSP)"},{"n":"3","title":"Contratos administrativos y privados (art. 25 LCSP)"},{"n":"4","title":"Necesidad, duración y objeto (arts. 28, 29 y 99 LCSP)"},{"n":"5","title":"Órgano de contratación y aptitud del contratista (arts. 61 y 65 LCSP)"},{"n":"6","title":"Valor estimado y garantías (arts. 101, 106 y 107 LCSP)"},{"n":"7","title":"Contratos menores (art. 118 LCSP)"},{"n":"8","title":"Procedimientos de adjudicación y prerrogativas (arts. 131-190 LCSP)"}]'::jsonb, '["Art. 1.1 Ley 9/2017: «a los principios de libertad de acceso a las licitaciones, publicidad y transparencia de los procedimientos, y no discriminación e igualdad de trato entre los licitadores»","Art. 2.1 Ley 9/2017: «los contratos onerosos, cualquiera que sea su naturaleza jurídica, que celebren las entidades enumeradas en el artículo 3.»","Art. 16.1 Ley 9/2017: «Son contratos de suministro los que tienen por objeto la adquisición, el arrendamiento financiero, o el arrendamiento, con o sin opción de compra, de productos o bienes muebles.»","Art. 17 Ley 9/2017: «No podrán ser objeto de estos contratos los servicios que impliquen ejercicio de la autoridad inherente a los poderes públicos.»","Art. 17 Ley 9/2017: «Son contratos de servicios aquellos cuyo objeto son prestaciones de hacer consistentes en el desarrollo de una actividad o dirigidas a la obtención de un resultado distinto de una obra o suministro»","Art. 25.1 Ley 9/2017: «a) Los contratos de obra, concesión de obra, concesión de servicios, suministro y servicios.»","Art. 28.1 Ley 9/2017: «no podrán celebrar otros contratos que aquellos que sean necesarios para el cumplimiento y realización de sus fines institucionales.»","Art. 29.4 Ley 9/2017: «Los contratos de suministros y de servicios de prestación sucesiva tendrán un plazo máximo de duración de cinco años, incluyendo las posibles prórrogas»","Art. 61.1 Ley 9/2017: «La representación de las entidades del sector público en materia contractual corresponde a los órganos de contratación, unipersonales o colegiados»","Art. 65.1 Ley 9/2017: «que tengan plena capacidad de obrar, no estén incursas en alguna prohibición de contratar»","Art. 99.1 Ley 9/2017: «El objeto de los contratos del sector público deberá ser determinado.»","Art. 101.1 Ley 9/2017: «el órgano de contratación tomará el importe total, sin incluir el Impuesto sobre el Valor Añadido, pagadero según sus estimaciones.»","Art. 107.1 Ley 9/2017: «deberán constituir a disposición del órgano de contratación una garantía de un 5 por 100 del precio final ofertado por aquellos»","Art. 106.1 Ley 9/2017: «En el procedimiento de contratación no procederá la exigencia de garantía provisional, salvo cuando de forma excepcional el órgano de contratación, por motivos de interés público, lo considere necesario»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902', null, null, null, null
  from public.topics t where t.slug = 'iipp-a10-contratos-sector-publico'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
