insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 45/2015, de 14 de octubre, de Voluntariado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11072', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-a11-voluntariado', 'Primera parte, tema 11. La Ley 45/2015, de Voluntariado') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a11-voluntariado' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto de voluntariado y actividades excluidas (art. 3)"},{"n":"2","title":"Límites, valores y principios (arts. 4-5)"},{"n":"3","title":"Ámbitos y programas de voluntariado (arts. 6-7)"},{"n":"4","title":"Los voluntarios: requisitos, derechos y deberes (arts. 8-11)"},{"n":"5","title":"Acuerdo de incorporación (art. 12)"},{"n":"6","title":"Entidades de voluntariado (art. 13)"}]'::jsonb, '["Art. 3.1 Ley 45/2015: «c) Que se lleven a cabo sin contraprestación económica o material, sin perjuicio del abono de los gastos reembolsables»","Art. 3.1 Ley 45/2015: «d) Que se desarrollen a través de entidades de voluntariado con arreglo a programas concretos»","Art. 3.3 Ley 45/2015: «b) Las ejecutadas por razones familiares, de amistad o de buena vecindad.»","Art. 3.3 Ley 45/2015: «f) Las prácticas no laborales en empresas o grupos empresariales y las prácticas académicas externas.»","Art. 4.2 Ley 45/2015: «La realización de actividades de voluntariado tampoco podrá sustituir a las Administraciones públicas en el desarrollo de funciones o en la prestación de servicios públicos a los que están obligadas por ley.»","Art. 4.1 Ley 45/2015: «La realización de actividades de voluntariado no podrá ser causa justificativa de extinción del contrato de trabajo.»","Art. 5.2 Ley 45/2015: «d) La complementariedad respecto a las actuaciones de las Administraciones públicas»","Art. 6.1 Ley 45/2015: «a) Voluntariado social, que se desarrolla mediante la intervención con las personas y la realidad social»","Art. 8.2 Ley 45/2015: «a) Los mayores de 16 y menores de 18 años deberán contar con el consentimiento de sus progenitores, tutores o representantes legales.»","Art. 8.2 Ley 45/2015: «b) Los menores de 16 años y mayores de 12 podrán llevar a cabo acciones de voluntariado si cuentan con la autorización expresa de sus progenitores»","Art. 9.1 Ley 45/2015: «Los trabajadores por cuenta ajena y los empleados públicos, sólo podrán realizar actividades de voluntariado fuera de la jornada laboral»","Art. 10.1 Ley 45/2015: «e) Estar cubiertos, a cargo de la entidad de voluntariado, de los riesgos de accidente y enfermedad derivados directamente del ejercicio de la acción voluntaria»","Art. 10.1 Ley 45/2015: «g) Disponer de una acreditación identificativa de su condición de voluntario»","Art. 11 Ley 45/2015: «c) Rechazar cualquier contraprestación material o económica que pudieran recibir»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11072'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11072', null, null, null, null
  from public.topics t where t.slug = 'iipp-a11-voluntariado'
