insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-a12-politicas-publicas-igualdad-dependencia', 'Primera parte, tema 12. Políticas de igualdad, violencia de género, discapacidad, dependencia y administración electrónica') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a12-politicas-publicas-igualdad-dependencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Igualdad efectiva de mujeres y hombres (LO 3/2007)"},{"n":"2","title":"Violencia de género (LO 1/2004)"},{"n":"3","title":"Autonomía personal y dependencia (Ley 39/2006)"},{"n":"4","title":"Administración electrónica: derecho y obligación de relacionarse electrónicamente (art. 14 LPAC)"},{"n":"5","title":"Registros y notificaciones electrónicas (arts. 16, 41 y 43 LPAC)"}]'::jsonb, '["Art. 3 LO 3/2007: «El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo»","Art. 4 LO 3/2007: «es un principio informador del ordenamiento jurídico y, como tal, se integrará y observará en la interpretación y aplicación de las normas jurídicas.»","Art. 6.1 LO 3/2007: «Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.»","Art. 7.1 LO 3/2007: «constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona»","Art. 11.1 LO 3/2007: «Tales medidas, que serán aplicables en tanto subsistan dichas situaciones, habrán de ser razonables y proporcionadas»","Art. 17 LO 3/2007: «El Gobierno, en las materias que sean de la competencia del Estado, aprobará periódicamente un Plan Estratégico de Igualdad de Oportunidades»","Art. 1.1 LO 1/2004: «por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.»","Art. 1.1 LO 1/2004: «como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres»","Art. 2 LO 1/2004: «a) Fortalecer las medidas de sensibilización ciudadana de prevención»","Art. 1.1 Ley 39/2006: «mediante la creación de un Sistema para la Autonomía y Atención a la Dependencia»","Art. 2 Ley 39/2006: «Autonomía: la capacidad de controlar, afrontar y tomar, por propia iniciativa, decisiones personales acerca de cómo vivir»","Art. 26.1 Ley 39/2006: «b) Grado II. Dependencia severa: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria dos o tres veces al día»","Art. 28.1 Ley 39/2006: «estableciéndose un plazo máximo de 3 meses para su resolución.»","Art. 14.1 Ley 39/2015: «Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', null, null, null, 'Otras normas citadas: LO 1/2004 (https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760), Ley 39/2006 (https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990), Ley 39/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565)'
  from public.topics t where t.slug = 'iipp-a12-politicas-publicas-igualdad-dependencia'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
