insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 19/2013, de 9 de diciembre, de transparencia, acceso a la información pública y buen gobierno (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-a13-gobierno-abierto-transparencia', 'Primera parte, tema 13. Gobierno abierto, transparencia, acceso a la información y buen gobierno') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a13-gobierno-abierto-transparencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Objeto de la Ley 19/2013"},{"n":"2","title":"Publicidad activa (art. 5)"},{"n":"3","title":"Derecho de acceso a la información pública y límites (arts. 12-14)"},{"n":"4","title":"Procedimiento: solicitud, inadmisión, tramitación y resolución (arts. 17-22)"},{"n":"5","title":"Reclamación ante el Consejo de Transparencia y Buen Gobierno (arts. 24 y 33)"},{"n":"6","title":"Buen gobierno (art. 26)"}]'::jsonb, '["Art. 1 Ley 19/2013: «Esta Ley tiene por objeto ampliar y reforzar la transparencia de la actividad pública, regular y garantizar el derecho de acceso a la información relativa a aquella actividad»","Art. 5.1 Ley 19/2013: «publicarán de forma periódica y actualizada la información cuyo conocimiento sea relevante para garantizar la transparencia de su actividad»","Art. 12 Ley 19/2013: «Todas las personas tienen derecho a acceder a la información pública, en los términos previstos en el artículo 105.b) de la Constitución Española»","Art. 13 Ley 19/2013: «Se entiende por información pública los contenidos o documentos, cualquiera que sea su formato o soporte, que obren en poder de alguno de los sujetos incluidos en el ámbito de aplicación de este título»","Art. 14.1 Ley 19/2013: «e) La prevención, investigación y sanción de los ilícitos penales, administrativos o disciplinarios.»","Art. 17.3 Ley 19/2013: «El solicitante no está obligado a motivar su solicitud de acceso a la información.»","Art. 18.1 Ley 19/2013: «a) Que se refieran a información que esté en curso de elaboración o de publicación general.»","Art. 18.1 Ley 19/2013: «b) Referidas a información que tenga carácter auxiliar o de apoyo como la contenida en notas, borradores, opiniones, resúmenes, comunicaciones e informes internos»","Art. 19.2 Ley 19/2013: «se pedirá al solicitante que la concrete en un plazo de diez días, con indicación de que, en caso de no hacerlo, se le tendrá por desistido»","Art. 20.1 Ley 19/2013: «en el plazo máximo de un mes desde la recepción de la solicitud por el órgano competente para resolver.»","Art. 20.1 Ley 19/2013: «Este plazo podrá ampliarse por otro mes en el caso de que el volumen o la complejidad de la información que se solicita así lo hagan necesario»","Art. 20.4 Ley 19/2013: «Transcurrido el plazo máximo para resolver sin que se haya dictado y notificado resolución expresa se entenderá que la solicitud ha sido desestimada.»","Art. 22.1 Ley 19/2013: «El acceso a la información se realizará preferentemente por vía electrónica»","Art. 22.1 Ley 19/2013: «Cuando no pueda darse el acceso en el momento de la notificación de la resolución deberá otorgarse, en cualquier caso, en un plazo no superior a diez días.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887', null, null, null, null
  from public.topics t where t.slug = 'iipp-a13-gobierno-abierto-transparencia'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
