insert into public.topics (slug, title) values ('iipp-a16-procedimiento-sancionador', 'Primera parte, tema 16. Régimen jurídico, procedimiento administrativo común y procedimiento sancionador') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a16-procedimiento-sancionador' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Principios de actuación de las Administraciones (art. 3 LRJSP)"},{"n":"2","title":"Principios de la potestad sancionadora (arts. 25-31 LRJSP)"},{"n":"3","title":"Derechos del presunto responsable (art. 53.2 LPAC)"},{"n":"4","title":"Iniciación del procedimiento sancionador (arts. 63-64 LPAC)"},{"n":"5","title":"Terminación, propuesta y resolución (arts. 85, 89 y 90 LPAC)"}]'::jsonb, '["Art. 3.1 Ley 40/2015: «actúan de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la Constitución, a la Ley y al Derecho.»","Art. 25.1 Ley 40/2015: «La potestad sancionadora de las Administraciones Públicas se ejercerá cuando haya sido expresamente reconocida por una norma con rango de Ley»","Art. 26.2 Ley 40/2015: «Las disposiciones sancionadoras producirán efecto retroactivo en cuanto favorezcan al presunto infractor o al infractor»","Art. 27.1 Ley 40/2015: «Sólo constituyen infracciones administrativas las vulneraciones del ordenamiento jurídico previstas como tales infracciones por una Ley»","Art. 28.1 Ley 40/2015: «que resulten responsables de los mismos a título de dolo o culpa.»","Art. 29.1 Ley 40/2015: «Las sanciones administrativas, sean o no de naturaleza pecuniaria, en ningún caso podrán implicar, directa o subsidiariamente, privación de libertad.»","Art. 29.2 Ley 40/2015: «El establecimiento de sanciones pecuniarias deberá prever que la comisión de las infracciones tipificadas no resulte más beneficioso para el infractor que el cumplimiento de las normas infringidas.»","Art. 30.1 Ley 40/2015: «las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses»","Art. 31.1 Ley 40/2015: «No podrán sancionarse los hechos que lo hayan sido penal o administrativamente, en los casos en que se aprecie identidad del sujeto, hecho y fundamento.»","Art. 53.2 Ley 39/2015: «b) A la presunción de no existencia de responsabilidad administrativa mientras no se demuestre lo contrario.»","Art. 63.1 Ley 39/2015: «Los procedimientos de naturaleza sancionadora se iniciarán siempre de oficio por acuerdo del órgano competente»","Art. 63.1 Ley 39/2015: «establecerán la debida separación entre la fase instructora y la sancionadora, que se encomendará a órganos distintos.»","Art. 64.1 Ley 39/2015: «y se notificará a los interesados, entendiendo en todo caso por tal al inculpado.»","Art. 85.1 Ley 39/2015: «si el infractor reconoce su responsabilidad, se podrá resolver el procedimiento con la imposición de la sanción que proceda.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', null, null, null, 'Otras normas citadas: Ley 39/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565)'
  from public.topics t where t.slug = 'iipp-a16-procedimiento-sancionador'
