insert into public.topics (slug, title) values ('iipp-a17-presupuesto-estabilidad', 'Primera parte, tema 17. El presupuesto del Estado y la estabilidad presupuestaria') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a17-presupuesto-estabilidad' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El presupuesto en la Constitución (art. 134 CE)"},{"n":"2","title":"Estabilidad presupuestaria (art. 135 CE y LO 2/2012)"},{"n":"3","title":"Principios de programación y gestión presupuestaria (arts. 26-29 LGP)"},{"n":"4","title":"Los Presupuestos Generales del Estado: definición, ámbito temporal y remisión (arts. 32-37 LGP)"},{"n":"5","title":"Carácter limitativo de los créditos (art. 46 LGP)"}]'::jsonb, '["Art. 134.1 CE: «Corresponde al Gobierno la elaboración de los Presupuestos Generales del Estado y a las Cortes Generales, su examen, enmienda y aprobación.»","Art. 134.2 CE: «Los Presupuestos Generales del Estado tendrán carácter anual»","Art. 134.3 CE: «al menos tres meses antes de la expiración de los del año anterior.»","Art. 134.4 CE: «se considerarán automáticamente prorrogados los Presupuestos del ejercicio anterior hasta la aprobación de los nuevos.»","Art. 134.2 CE: «incluirán la totalidad de los gastos e ingresos del sector público estatal y en ellos se consignará el importe de los beneficios fiscales que afecten a los tributos del Estado.»","Art. 135.1 CE: «Todas las Administraciones Públicas adecuarán sus actuaciones al principio de estabilidad presupuestaria.»","Art. 135.2 CE: «Las Entidades Locales deberán presentar equilibrio presupuestario.»","Art. 135.3 CE: «El Estado y las Comunidades Autónomas habrán de estar autorizados por ley para emitir deuda pública o contraer crédito.»","Art. 32 Ley 47/2003: «Los Presupuestos Generales del Estado constituyen la expresión cifrada, conjunta y sistemática de los derechos y obligaciones a liquidar durante el ejercicio»","Art. 37.1 Ley 47/2003: «será remitido a las Cortes Generales antes del día 1 de octubre del año anterior al que se refiera.»","Art. 27.2 Ley 47/2003: «se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados»","Art. 27.1 Ley 47/2003: «La gestión del sector público estatal está sometida al régimen de presupuesto anual aprobado por las Cortes Generales y enmarcado en los límites de un escenario plurianual.»","Art. 29.1 Ley 47/2003: «se desarrollarán en programas plurianuales, referidos a los tres ejercicios siguientes»","Art. 26.1 Ley 47/2003: «La programación presupuestaria se regirá por los principios de estabilidad presupuestaria, sostenibilidad financiera, plurianualidad»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, 'Otras normas citadas: Ley 47/2003 (https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614)'
  from public.topics t where t.slug = 'iipp-a17-presupuesto-estabilidad'
