insert into public.topics (slug, title) values ('iipp-b06-integridad-moral-sexual-falsedades', 'Derecho Penal, tema 6. Torturas, libertad sexual, honor, falsedades, usurpación de funciones e intrusismo') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-b06-integridad-moral-sexual-falsedades' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Torturas y otros delitos contra la integridad moral (arts. 173-175 CP)"},{"n":"2","title":"Agresiones sexuales y consentimiento (arts. 178-181 CP)"},{"n":"3","title":"Calumnia e injuria (arts. 205-210 CP)"},{"n":"4","title":"Falsedades documentales (arts. 390-392 CP)"},{"n":"5","title":"Usurpación de funciones públicas e intrusismo (arts. 402-403 CP)"}]'::jsonb, '["Art. 174.1 Código Penal: «Comete tortura la autoridad o funcionario público que, abusando de su cargo»","Art. 174.2 Código Penal: «la autoridad o funcionario de instituciones penitenciarias o de centros de protección o corrección de menores que cometiere, respecto de detenidos, internos o presos, los actos a que se refiere el apartado anterior.»","Art. 174.1 Código Penal: «Además de las penas señaladas se impondrá, en todo caso, la pena de inhabilitación absoluta de ocho a 12 años.»","Art. 174.1 Código Penal: «El culpable de tortura será castigado con la pena de prisión de dos a seis años si el atentado fuera grave, y de prisión de uno a tres años si no lo es.»","Art. 175 Código Penal: «será castigado con la pena de prisión de dos a cuatro años si el atentado fuera grave, y de prisión de seis meses a dos años si no lo es.»","Art. 173.1 Código Penal: «El que infligiera a otra persona un trato degradante, menoscabando gravemente su integridad moral, será castigado con la pena de prisión de seis meses a dos años.»","Art. 178.1 Código Penal: «Sólo se entenderá que hay consentimiento cuando se haya manifestado libremente mediante actos que, en atención a las circunstancias del caso, expresen de manera clara la voluntad de la persona.»","Art. 178.1 Código Penal: «Será castigado con la pena de prisión de uno a cuatro años, como responsable de agresión sexual»","Art. 179.1 Código Penal: «el responsable será castigado como reo de violación con la pena de prisión de cuatro a doce años.»","Art. 181.1 Código Penal: «El que realizare actos de carácter sexual con un menor de dieciséis años, será castigado con la pena de prisión de dos a seis años.»","Art. 205 Código Penal: «Es calumnia la imputación de un delito hecha con conocimiento de su falsedad o temerario desprecio hacia la verdad.»","Art. 208 Código Penal: «Solamente serán constitutivas de delito las injurias que, por su naturaleza, efectos y circunstancias, sean tenidas en el concepto público por graves»","Art. 210 Código Penal: «El acusado de injuria quedará exento de responsabilidad probando la verdad de las imputaciones cuando estas se dirijan contra funcionarios públicos sobre hechos concernientes al ejercicio de sus cargos»","Art. 206 Código Penal: «Las calumnias serán castigadas con las penas de prisión de seis meses a dos años o multa de doce a 24 meses, si se propagaran con publicidad»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
  from public.topics t where t.slug = 'iipp-b06-integridad-moral-sexual-falsedades'
