insert into public.topics (slug, title) values ('iipp-b10-procedimientos-habeas-recursos', 'Derecho Penal, tema 10. Procedimiento ordinario y abreviado, habeas corpus y recursos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-b10-procedimientos-habeas-recursos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El habeas corpus: objeto y competencia (arts. 1-2 LO 6/1984)"},{"n":"2","title":"Legitimación e iniciación (arts. 3-5 LO 6/1984)"},{"n":"3","title":"Tramitación y resolución (arts. 6-9 LO 6/1984)"},{"n":"4","title":"Recursos contra resoluciones del Juez de Instrucción (arts. 216-217 LECrim)"},{"n":"5","title":"Procedimiento abreviado y apelación (arts. 757 y 790 LECrim)"},{"n":"6","title":"Enjuiciamiento rápido y conformidad (art. 801 LECrim)"},{"n":"7","title":"Casación (art. 847 LECrim)"},{"n":"8","title":"Libertad provisional (arts. 528-529 LECrim)"}]'::jsonb, '["Art. 1 LO 6/1984: «se podrá obtener la inmediata puesta a disposición de la Autoridad judicial competente, de cualquier persona detenida ilegalmente.»","Art. 1 LO 6/1984: «d) Las privadas de libertad a quienes no les sean respetados los derechos que la Constitución y las leyes procesales garantizan a toda persona detenida.»","Art. 2 LO 6/1984: «Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad»","Art. 2 LO 6/1984: «el procedimiento deberá seguirse ante el Juez Central de Instrucción correspondiente.»","Art. 3 LO 6/1984: «b) El Ministerio Fiscal. c) El Defensor del Pueblo. d) El abogado defensor del privado de libertad.»","Art. 4 LO 6/1984: «El procedimiento se iniciará, salvo cuando se incoe de oficio, por medio de escrito o comparecencia, no siendo preceptiva la intervención de Abogado ni de Procurador.»","Art. 5 LO 6/1984: «estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus»»","Art. 6 LO 6/1984: «Contra la resolución que en uno u otro caso se adopte, no cabrá recurso alguno.»","Art. 7 LO 6/1984: «En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación»","Art. 8 LO 6/1984: «en establecimiento distinto, o bajo la custodia de personas distintas a las que hasta entonces la detentaban.»","Art. 9 LO 6/1984: «si se apreciase temeridad o mala fe, será condenado el solicitante al pago de las costas del procedimiento»","Art. 216 LECrim: «Contra las resoluciones del Juez de Instrucción podrán ejercitarse los recursos de reforma, apelación y queja.»","Art. 217 LECrim: «El recurso de reforma podrá interponerse contra todos los autos del Juez de Instrucción.»","Art. 757 LECrim: «se aplicará al enjuiciamiento de los delitos castigados con pena privativa de libertad no superior a nueve años»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620', null, null, null, 'Otras normas citadas: LECrim (https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036)'
  from public.topics t where t.slug = 'iipp-b10-procedimientos-habeas-recursos'
