insert into public.topics (slug, title) values ('iipp-c04-prestaciones', 'Derecho Penitenciario, tema 4. Prestaciones: asistencia sanitaria, higiene y alimentación, asistencia religiosa y acción social') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c04-prestaciones' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Asistencia sanitaria (arts. 207-220 RP)"},{"n":"2","title":"Higiene y alimentación (art. 21 LOGP)"},{"n":"3","title":"Asistencia religiosa (art. 230 RP)"},{"n":"4","title":"Acción social penitenciaria (arts. 227-229 RP; arts. 73-75 LOGP)"}]'::jsonb, '["Art. treinta y siete LOGP: «a) De una enfermería, que contará con un número suficiente de camas […] b) De una dependencia destinada a la observación psiquiátrica y a la atención de los toxicómanos. c) De una unidad para enfermos contagiosos.»","Art. treinta y ocho.Dos LOGP: «Las internas podrán tener en su compañía a los hijos que no hayan alcanzado los tres años de edad, siempre que acrediten debidamente su filiación.»","Art. treinta y ocho.Tres LOGP: «Reglamentariamente se establecerá un régimen específico de visitas para los menores que no superen los diez años y no convivan con la madre en el centro penitenciario.»","Art. veintiuno.Dos LOGP: «La Administración proporcionará a los internos una alimentación controlada por el Médico»","Art. 207.1 RP: «La asistencia sanitaria tendrá carácter integral y estará orientada tanto a la prevención como a la curación y la rehabilitación.»","Art. 208.1 RP: «A todos los internos sin excepción se les garantizará una atención médico-sanitaria equivalente a la dispensada al conjunto de la población.»","Art. 209.1 RP: «Los Establecimientos penitenciarios contarán con un equipo sanitario de atención primaria que estará integrado, al menos, por un médico general, un diplomado en enfermería y un auxiliar de enfermería.»","Art. 209.2 RP: «La asistencia especializada se asegurará, preferentemente, a través del Sistema Nacional de Salud.»","Art. 210.1 RP: «Sólo cuando exista peligro inminente para la vida de éste se podrá imponer un tratamiento contra la voluntad del interesado, siendo la intervención médica la estrictamente necesaria para intentar salvar la vida del paciente»","Art. 212.1 RP: «Al frente del equipo sanitario se hallará un Subdirector médico o Jefe de los servicios médicos, que estará a las órdenes inmediatas del Director del Establecimiento.»","Art. 214.1 RP: «El reconocimiento se llevará a cabo durante las primeras veinticuatro horas a partir del ingreso.»","Art. 215.1 RP: «Los datos integrados en la historia clínica individual tendrán carácter confidencial, debiendo quedar correctamente archivados y custodiados, siendo únicamente accesibles para el personal autorizado.»","Art. 216.1 RP: «se autorizará a que uno o dos familiares o allegados puedan comunicar con él en la enfermería del Centro.»","Art. 218.1 RP: «quien, previa autorización del Centro Directivo, dispondrá lo necesario para efectuar el traslado. En todo caso se acompañará informe médico.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, 'Otras normas citadas: LOGP (https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708)'
  from public.topics t where t.slug = 'iipp-c04-prestaciones'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
