insert into public.topics (slug, title) values ('iipp-c05-regimen-ingreso-comunicaciones-traslados', 'Derecho Penitenciario, tema 5. Régimen (1): ingreso, comunicaciones y visitas, participación, quejas y recursos, conducciones y traslados') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c05-regimen-ingreso-comunicaciones-traslados' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ingreso en un establecimiento penitenciario (arts. 15-16 RP)"},{"n":"2","title":"Comunicaciones y visitas (art. 51 LOGP; arts. 41-49 RP)"},{"n":"3","title":"Participación de los internos en las actividades"},{"n":"4","title":"Información, quejas y recursos (arts. 52-54 RP)"},{"n":"5","title":"Conducciones y traslados (arts. 31-40 RP)"}]'::jsonb, '["Art. 15.1 RP: «El ingreso de una persona en prisión en calidad de detenido, preso o penado se efectuará mediante orden judicial de detención, mandamiento de prisión o sentencia firme de la autoridad judicial competente»","Art. 15.2 RP: «La Dirección del centro podrá denegar motivadamente el ingreso cuando en la orden de detención que se entregue no consten expresamente los citados extremos.»","Art. 16.3 RP: «En los casos de ingresos voluntarios, el Director del centro recabará del Juez o Tribunal, dentro de las veinticuatro horas siguientes al ingreso, el correspondiente mandamiento»","Art. 16.4 RP: «Si, transcurrido el plazo de las setenta y dos horas siguientes al ingreso, no se hubiese recibido en el centro la documentación que legalice el mismo, se procederá a la excarcelación del ingresado.»","Art. 18.1 RP: «se procederá a verificar su identidad personal, efectuando la reseña alfabética, dactilar y fotográfica, así como a la inscripción en el libro de ingresos»","Art. 19.1 RP: «Únicamente podrá comunicar con las personas que tengan expresa autorización del Juez.»","Art. 20.2 RP: «se formule propuesta de inclusión en uno de los grupos de separación interior y se ordene por el Director el traslado al departamento que corresponda, previo informe médico.»","Art. 23.1 RP: «los detenidos serán excarcelados por el Director del establecimiento o quien reglamentariamente le sustituya, al vencimiento del plazo máximo de detención o transcurridas las setenta y dos horas siguientes al momento del ingreso.»","Art. 31.1 RP: «el centro directivo tiene competencia exclusiva para decidir, con carácter ordinario o extraordinario, la clasificación y destino de los reclusos en los distintos establecimientos penitenciarios»","Art. 31.3 RP: «Los traslados se notificarán, si se trata de penados, al Juez de Vigilancia»","Art. 32 RP: «Las órdenes de conducción de los reclusos, dictadas por el centro directivo, se llevarán a cabo por las Fuerzas y Cuerpos de Seguridad del Estado que tengan a su cargo este cometido»","Art. 36.3 RP: «Excepcionalmente y sólo en casos de urgencia o necesidad perentoria, podrá disponerse el traslado de internos a cargo de los funcionarios de instituciones penitenciarias que el Director del establecimiento designe entre los que se hallen de servicio.»","Art. 41.3 RP: «Todo interno tiene derecho a comunicar inmediatamente a su familia y abogado su ingreso en un centro penitenciario»","Art. 42 RP: «como mínimo, dos comunicaciones a la semana […] una comunicación de veinte minutos de duración como mínimo, no pudiendo comunicar más de cuatro personas simultáneamente con el mismo interno.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c05-regimen-ingreso-comunicaciones-traslados'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
