insert into public.topics (slug, title) values ('iipp-c07-establecimientos-regimen-ordinario', 'Derecho Penitenciario, tema 7. Tipos de establecimientos, régimen ordinario y régimen de preventivos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c07-establecimientos-regimen-ordinario' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Tipos de establecimientos (arts. 7-12 LOGP; arts. 10-13 RP)"},{"n":"2","title":"Régimen ordinario (arts. 76-79 RP)"},{"n":"3","title":"Régimen de preventivos (arts. 96-98 RP)"},{"n":"4","title":"Principios del régimen (art. 73 RP)"}]'::jsonb, '["Art. séptimo LOGP: «Los establecimientos penitenciarios comprenderán: a) Establecimientos de preventivos. b) Establecimientos de cumplimiento de penas. c) Establecimientos especiales.»","Art. octavo.Uno LOGP: «También podrán cumplirse penas y medidas penales privativas de libertad cuando el internamiento efectivo pendiente no exceda de seis meses.»","Art. octavo.Dos LOGP: «En cada provincia podrá existir más de un establecimiento de esta naturaleza.»","Art. noveno.Uno LOGP: «Se organizarán separadamente para hombres y mujeres y serán de dos tipos: de régimen ordinario y abierto.»","Art. once LOGP: «Los establecimientos especiales son aquellos en los que prevalece el carácter asistencial y serán de los siguientes tipos: a) Centros hospitalarios. b) Centros psiquiátricos. c) Centros de rehabilitación social»","Art. doce.Dos LOGP: «Los establecimientos penitenciarios no deberán acoger más de trescientos cincuenta internos por unidad.»","Art. doce.Uno LOGP: «se procurará que cada una cuente con el número suficiente de aquéllos para satisfacer las necesidades penitenciarias y evitar el desarraigo social de los penados.»","Art. 10.1 RP: «por establecimiento o centro se entiende una entidad arquitectónica, administrativa y funcional con organización propia.»","Art. 12.1 RP: «Se entiende por establecimiento polivalente aquel que cumple los diversos fines previstos en los artículos 7 a 11 de la Ley Orgánica General Penitenciaria.»","Art. 13.2 RP: «Temporalmente, cuando la población penitenciaria supere el número de plazas individuales disponibles, se podrá albergar a más de un interno por celda.»","Art. 73.1 RP: «Por régimen penitenciario se entiende el conjunto de normas o medidas que persiguen la consecución de una convivencia ordenada y pacífica que permita alcanzar el ambiente adecuado para el éxito del tratamiento y la retención y custodia de los reclusos.»","Art. 74.1 RP: «El régimen ordinario se aplicará a los penados clasificados en segundo grado, a los penados sin clasificar y a los detenidos y presos.»","Art. 75.2 RP: «a solicitud del interno o por propia iniciativa, el Director podrá acordar mediante resolución motivada, cuando fuere preciso para salvaguardar la vida o integridad física del recluso, la adopción de medidas que impliquen limitaciones regimentales, dando cuenta al Juez de Vigilancia.»","Art. 76.3 RP: «El trabajo y la formación tendrán la consideración de actividad básica en la vida del Centro.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708', null, null, null, 'Otras normas citadas: RP (https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307)'
  from public.topics t where t.slug = 'iipp-c07-establecimientos-regimen-ordinario'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
