insert into public.topics (slug, title) values ('iipp-c10-tratamiento-programas', 'Derecho Penitenciario, tema 10. Tratamiento (2): elementos y programas, formación, cultura y deporte') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c10-tratamiento-programas' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El tratamiento: concepto y principios (art. 59 LOGP; arts. 110-113 RP)"},{"n":"2","title":"Programas de tratamiento y módulos (arts. 114-117 RP)"},{"n":"3","title":"Programas específicos (arts. 116-117 RP)"},{"n":"4","title":"Formación, cultura y deporte (arts. 118-131 RP)"}]'::jsonb, '["Art. cincuenta y nueve.Uno LOGP: «El tratamiento penitenciario consiste en el conjunto de actividades directamente dirigidas a la consecución de la reeducación y reinserción social de los penados.»","Art. cincuenta y nueve.Dos LOGP: «El tratamiento pretende hacer del interno una persona con la intención y la capacidad de vivir respetando la Ley penal, así como de subvenir a sus necesidades.»","Art. 110 RP: «a) Diseñará programas formativos orientados a desarrollar las aptitudes de los internos […] b) Utilizará los programas y las técnicas de carácter psicosocial»","Art. 111.1 RP: «Las tareas de observación, clasificación y tratamiento penitenciarios las realizarán las Juntas de Tratamiento y sus decisiones serán ejecutadas por los Equipos Técnicos»","Art. 114.4 RP: «Las salidas programadas serán propuestas por la Junta de Tratamiento, que solicitará la aprobación del Centro Directivo y la posterior autorización del Juez de Vigilancia»","Art. 114.5 RP: «Como regla general, la duración de las salidas programadas no será superior a dos días y, en ningún caso, se computarán dentro de los límites establecidos para los permisos ordinarios en el artículo 154.»","Art. 114.2 RP: «los internos serán acompañados por personal del Centro penitenciario o de otras instituciones o por voluntarios que habitualmente realicen actividades relacionadas con el tratamiento penitenciario de los reclusos.»","Art. 115.2 RP: «la Junta de Tratamiento que esté al frente del mismo asumirá las funciones que tienen atribuidas el Consejo de Dirección y la Comisión Disciplinaria del Centro penitenciario, con exclusión de las que se refieran a los aspectos económico-administrativos.»","Art. 116.1 RP: «debe tener a su alcance la posibilidad de seguir programas de tratamiento y deshabituación, con independencia de su situación procesal y de sus vicisitudes penales y penitenciarias.»","Art. 117.1 RP: «Los internos clasificados en segundo grado de tratamiento que presenten un perfil de baja peligrosidad social y no ofrezcan riesgos de quebrantamiento de condena, podrán acudir regularmente a una institución exterior»","Art. 118.1 RP: «Las actividades educativas, formativas, socioculturales y deportivas se determinarán por el Consejo de Dirección»","Art. 119.2 RP: «que no deberán contener indicación alguna relativa a su obtención en un Establecimiento penitenciario.»","Art. 121.1 RP: «El Centro Directivo podrá conceder, previo informe de la Junta de Tratamiento, traslados de Establecimiento por motivos educativos»","Art. 122.2 RP: «que tendrán carácter obligatorio sólo cuando los internos carezcan de los conocimientos propios de la formación de las enseñanzas básicas.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, 'Otras normas citadas: LOGP (https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708)'
  from public.topics t where t.slug = 'iipp-c10-tratamiento-programas'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 782/2001, de 6 de julio, relación laboral especial de los penados en talleres penitenciarios (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-c11-relacion-laboral-tpfe', 'Derecho Penitenciario, tema 11. La relación laboral especial penitenciaria y la Entidad Estatal TPFE') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c11-relacion-laboral-tpfe' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La relación laboral especial penitenciaria (RD 782/2001)"},{"n":"2","title":"Derechos y deberes laborales de los internos"},{"n":"3","title":"Suspensión y extinción de la relación laboral"},{"n":"4","title":"La Entidad Estatal TPFE (RD 122/2015)"}]'::jsonb, '["Art. 1.1 RD 782/2001: «así como la de quienes cumplen penas de trabajo en beneficio de la comunidad.»","Art. 1.2 RD 782/2001: «Queda excluida de su ámbito de aplicación la relación laboral de los internos en régimen abierto, sometidos a un sistema de contratación ordinaria con empresarios, que se regulará por la legislación laboral común»","Art. 2.2 RD 782/2001: «el empleador será en todos los casos el Organismo Autónomo Trabajo y Prestaciones Penitenciarias u órgano autonómico equivalente.»","Art. 3.2 RD 782/2001: «La Junta de Tratamiento, como órgano administrativo competente, adjudicará los puestos a los internos»","Art. 3.2 RD 782/2001: «1.º Los internos en cuyo programa individualizado de tratamiento se contemple el desarrollo de una actividad laboral. 2.º Los internos penados sobre los preventivos.»","Art. 7.1 RD 782/2001: «La relación laboral especial penitenciaria se formalizará con la inscripción del interno en el correspondiente Libro de Matrícula, con efectos desde la fecha en que se produzca el alta efectiva en el puesto de trabajo.»","Art. 8.1 RD 782/2001: «a) Operario base: los que desempeñen el conjunto de tareas necesarias para el funcionamiento de los talleres productivos. b) Operario superior»","Art. 9.2 RD 782/2001: «Suspensión de empleo y sueldo por el cumplimiento de sanciones disciplinarias penitenciarias de aislamiento.»","Art. 10.2 RD 782/2001: «Por traslado del interno trabajador a otro establecimiento penitenciario por un período superior a dos meses.»","Art. 10.3 RD 782/2001: «La extinción de la relación laboral penitenciaria se acordará, previa valoración de las circunstancias de cada caso, por el Director del centro penitenciario en su calidad de delegado»","Art. 14.1 RD 782/2001: «los internos que hubiesen desempeñado un puesto de trabajo en un centro penitenciario por un período superior a un año»","Art. 15.2 RD 782/2001: «para cuyo cálculo se tomará como referencia el salario mínimo interprofesional vigente en cada momento»","Art. 16.1 RD 782/2001: «efectuará el pago de las retribuciones mediante su ingreso mensual en la cuenta de peculio del interno.»","Art. 17.2 RD 782/2001: «Los internos trabajadores tendrán derecho a un descanso semanal de día y medio ininterrumpido que se disfrutará, con carácter general, la tarde del sábado y el día completo del domingo»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171', null, null, null, null
  from public.topics t where t.slug = 'iipp-c11-relacion-laboral-tpfe'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
