insert into public.topics (slug, title) values ('iipp-c12-permisos-salida', 'Derecho Penitenciario, tema 12. Los permisos de salida') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c12-permisos-salida' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Permisos de salida ordinarios (art. 47.2 LOGP; art. 154 RP)"},{"n":"2","title":"Permisos extraordinarios (art. 47.1 LOGP; art. 155 RP)"},{"n":"3","title":"Requisitos y procedimiento de concesión (arts. 156-162 RP)"},{"n":"4","title":"Salidas programadas"}]'::jsonb, '["Art. 154.1 RP: «permisos de salida ordinarios de hasta siete días de duración como preparación para la vida en libertad»","Art. 154.1 RP: «hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados clasificados en segundo o tercer grado respectivamente»","Art. 154.1 RP: «siempre que hayan extinguido la cuarta parte de la condena o condenas y no observen mala conducta.»","Art. 154.2 RP: «se distribuirán, como regla general, en los dos semestres naturales de cada año, concediendo en cada uno de ellos hasta dieciocho y veinticuatro días, respectivamente.»","Art. 154.3 RP: «Dentro de los indicados límites no se computarán las salidas de fin de semana propias del régimen abierto ni las salidas programadas que se regulan en el artículo 114 de este Reglamento, ni los permisos extraordinarios regulados en el artículo siguiente.»","Art. 155.1 RP: «se concederán, con las medidas de seguridad adecuadas en su caso, permisos de salida extraordinarios, salvo que concurran circunstancias excepcionales que lo impidan.»","Art. 155.2 RP: «La duración de cada permiso extraordinario vendrá determinada por su finalidad y no podrá exceder del límite fijado en el artículo anterior para los permisos ordinarios.»","Art. 155.3 RP: «Cuando se trate de internos clasificados en primer grado será necesaria la autorización expresa del Juez de Vigilancia.»","Art. 155.4 RP: «permisos extraordinarios de salida de hasta doce horas de duración para consulta ambulatoria extrapenitenciaria»","Art. 156.1 RP: «resulte probable el quebrantamiento de la condena, la comisión de nuevos delitos o una repercusión negativa de la salida sobre el interno»","Art. 156.2 RP: «El Equipo Técnico establecerá, en su informe, las condiciones y controles que se deban observar, en su caso, durante el disfrute del permiso de salida»","Art. 157.1 RP: «la Dirección podrá suspender motivadamente con carácter provisional el permiso, poniéndose en conocimiento de la Autoridad administrativa o judicial competente la suspensión para que resuelva lo que proceda.»","Art. 157.2 RP: «Si el interno aprovechase el disfrute de cualquier clase de permiso para fugarse o cometiese un nuevo delito durante el mismo, quedará sin efecto el permiso concedido»","Art. 158.2 RP: «En ningún caso se concederá un permiso extraordinario cuando el supuesto de hecho o las circunstancias concurrentes permitan su tramitación como permiso ordinario.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c12-permisos-salida'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-c13-libertad-condicional-beneficios', 'Derecho Penitenciario, tema 13. Libertad y excarcelación, expulsión de extranjeros, libertad condicional y beneficios penitenciarios') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c13-libertad-condicional-beneficios' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Libertad y excarcelación (arts. 22-30 RP)"},{"n":"2","title":"Expulsión de extranjeros (LO 4/2000)"},{"n":"3","title":"Libertad condicional (arts. 90-92 CP; arts. 192-201 RP)"},{"n":"4","title":"Beneficios penitenciarios (arts. 202-206 RP)"}]'::jsonb, '["Art. 24.1 RP: «será necesaria la aprobación de la libertad definitiva por el Tribunal sentenciador o del expediente de libertad condicional por el Juez de Vigilancia.»","Art. 24.2 RP: «Con una antelación mínima de dos meses al cumplimiento de la condena, el Director del establecimiento formulará al Tribunal sentenciador una propuesta de libertad definitiva»","Art. 90.1 Código Penal: «a) Que se encuentre clasificado en tercer grado. b) Que haya extinguido las tres cuartas partes de la pena impuesta. c) Que haya observado buena conducta.»","Art. 90.1 Código Penal: «No se concederá la suspensión si el penado no hubiese satisfecho la responsabilidad civil derivada del delito en los supuestos y conforme a los criterios establecidos por los apartados 5 y 6 del artículo 72»","Art. 90.2 Código Penal: «a) Que hayan extinguido dos terceras parte de su condena. b) Que durante el cumplimiento de su pena hayan desarrollado actividades laborales, culturales u ocupacionales»","Art. 90.2 Código Penal: «podrá adelantar, una vez extinguida la mitad de la condena, la concesión de la libertad condicional en relación con el plazo previsto en el apartado anterior, hasta un máximo de noventa días por cada año transcurrido de cumplimiento efectivo de condena.»","Art. 90.3 Código Penal: «a) Que se encuentren cumpliendo su primera condena de prisión y que ésta no supere los tres años de duración. b) Que hayan extinguido la mitad de su condena.»","Art. 90.3 Código Penal: «Este régimen no será aplicable a los penados que lo hayan sido por la comisión de un delito contra la libertad e indemnidad sexuales.»","Art. 90.5 Código Penal: «El plazo de suspensión de la ejecución del resto de la pena será de dos a cinco años. En todo caso, el plazo de suspensión de la ejecución y de libertad condicional no podrá ser inferior a la duración de la parte de pena pendiente de cumplimiento.»","Art. 90.6 Código Penal: «El tiempo transcurrido en libertad condicional no será computado como tiempo de cumplimiento de la condena.»","Art. 90.7 Código Penal: «el juez o tribunal podrá fijar un plazo de seis meses, que motivadamente podrá ser prolongado a un año, hasta que la pretensión pueda ser nuevamente planteada.»","Art. 89.1 Código Penal: «Las penas de prisión de más de un año impuestas a un ciudadano extranjero serán sustituidas por su expulsión del territorio español.»","Art. 89.5 Código Penal: «El extranjero no podrá regresar a España en un plazo de cinco a diez años, contados desde la fecha de su expulsión»","Art. 89.6 Código Penal: «La expulsión llevará consigo el archivo de cualquier procedimiento administrativo que tuviera por objeto la autorización para residir o trabajar en España.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, 'Otras normas citadas: RP (https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307)'
  from public.topics t where t.slug = 'iipp-c13-libertad-condicional-beneficios'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
