insert into public.topics (slug, title) values ('iipp-c14-formas-especiales-ejecucion', 'Derecho Penitenciario, tema 14. Formas especiales de ejecución, prisión permanente revisable, TBC, suspensiones y localización permanente') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c14-formas-especiales-ejecucion' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Formas especiales de ejecución (arts. 165-188 RP)"},{"n":"2","title":"La prisión permanente revisable (arts. 36 y 92 CP)"},{"n":"3","title":"Trabajos en beneficio de la comunidad y suspensiones (RD 840/2011)"},{"n":"4","title":"Localización permanente (RD 840/2011)"}]'::jsonb, '["Art. 165.1 RP: «Las Unidades Dependientes son unidades arquitectónicamente ubicadas fuera del recinto de los Centros penitenciarios, preferentemente en viviendas ordinarias del entorno comunitario, sin ningún signo de distinción externa relativo a su dedicación.»","Art. 165.3 RP: «Administrativamente dependerán siempre de un Centro penitenciario»","Art. 166.1 RP: «La creación de nuevas Unidades Dependientes se llevará a cabo mediante Orden Ministerial o resolución autonómica equivalente»","Art. 167.1 RP: «La selección de los internos que hayan de ser destinados a una Unidad Dependiente se llevará a cabo por la Junta de Tratamiento»","Art. 168 RP: «Con carácter excepcional, el Centro Directivo, de conformidad con lo dispuesto en el artículo 16, a), de la Ley Orgánica General Penitenciaria podrá, para ejecutar programas específicos de tratamiento o para evitar la desestructuración familiar»","Art. 169.2 RP: «No podrán ser destinados a estos Departamentos Mixtos los internos condenados por delitos contra la libertad sexual.»","Art. 173.1 RP: «Se considera jóvenes a los internos menores de veintiún años y, excepcionalmente, los que no hayan alcanzado los veinticinco años de edad.»","Art. 178 RP: «Los menores tendrán cubierta la asistencia médica en el Establecimiento por un especialista en Pediatría.»","Art. 178 RP: «El régimen de visitas del menor sólo podrá restringirse de forma transitoria por razones de orden y de seguridad del Establecimiento.»","Art. 179 RP: «la Junta de Tratamiento podrá aprobar un horario adecuado a sus necesidades familiares con el fin de fomentar el contacto con sus hijos en el ambiente familiar, pudiendo pernoctar en el domicilio»","Art. 182.1 RP: «El Centro Directivo podrá autorizar la asistencia en instituciones extrapenitenciarias adecuadas, públicas o privadas, de penados clasificados en tercer grado que necesiten un tratamiento específico para deshabituación de drogodependencias y otras adicciones, dando cuenta al Juez de Vigilancia.»","Art. 187.1 RP: «la situación personal del paciente será revisada, al menos, cada seis meses por el Equipo multidisciplinar»","Art. 188.4 RP: «Las disposiciones de régimen disciplinario contenidas en este Reglamento no serán de aplicación a los pacientes internados en estas instituciones.»","Art. 188.3 RP: «El empleo de medios coercitivos es una medida excepcional, que sólo podrá ser admitida por indicación del facultativo»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c14-formas-especiales-ejecucion'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
