insert into public.topics (slug, title) values ('iipp-c15-regimen-disciplinario', 'Derecho Penitenciario, tema 15. El régimen disciplinario y las recompensas') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c15-regimen-disciplinario' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Principios del régimen disciplinario (arts. 41-45 LOGP; arts. 231-232 RP)"},{"n":"2","title":"Faltas muy graves, graves y leves (arts. 108-110 RP 1981)"},{"n":"3","title":"Sanciones y su ejecución (arts. 233-236 RP)"},{"n":"4","title":"Procedimiento sancionador (arts. 241-252 RP)"},{"n":"5","title":"Recompensas (art. 46 LOGP; arts. 263-264 RP)"}]'::jsonb, '["Art. 231.1 RP: «El régimen disciplinario de los reclusos estará dirigido a garantizar la seguridad y el buen orden regimental y a conseguir una convivencia ordenada»","Art. 232.1 RP: «La potestad disciplinaria se ejercerá por la Comisión Disciplinaria, sin perjuicio de las atribuciones del Director para la imposición de sanciones por faltas leves»","Art. 233.1 RP: «Sanción de aislamiento en celda de seis a catorce días de duración, siempre que se haya manifestado una evidente agresividad o violencia por parte del interno»","Art. 233.2 RP: «Las restantes faltas graves se sancionarán con privación de permisos de salida por tiempo igual o inferior a dos meses»","Art. 233.3 RP: «sólo podrán corregirse con privación de paseos y actos recreativos comunes de hasta tres días de duración y con amonestación.»","Art. 236.2 RP: «el máximo de cumplimiento no podrá exceder nunca del triplo del tiempo correspondiente a la sanción más grave, ni de cuarenta y dos días consecutivos en caso de aislamiento en celda.»","Art. 241.1 RP: «el Director del Establecimiento acordará de oficio y motivadamente la iniciación del procedimiento sancionador»","Art. 242.1 RP: «El Director nombrará Instructor al funcionario que estime conveniente, excluyendo al que haya practicado la información previa y a los que puedan estar implicados en los hechos.»","Art. 243.1 RP: «El Director, en el ámbito de las facultades que le atribuye este Reglamento, por sí o a propuesta del Instructor del expediente disciplinario, podrá acordar en cualquier momento del procedimiento, mediante acuerdo motivado, las medidas cautelares»","Art. 246.2 RP: «El acuerdo deberá dictarse en el plazo máximo de tres meses desde la iniciación del procedimiento disciplinario.»","Art. 248.b) RP: «recurso ante el Juez de Vigilancia, verbalmente en el mismo acto de la notificación o por escrito dentro de los cinco días hábiles siguientes a la misma»","Art. 252.1 RP: «Los acuerdos sancionadores no serán ejecutivos en tanto no haya sido resuelto el recurso interpuesto por el interno ante el Juez de Vigilancia o, en caso de que no se haya interpuesto, hasta que haya transcurrido el plazo para su impugnación.»","Art. 253.1 RP: «Las sanciones de aislamiento en celda de duración superior a catorce días no serán en ningún caso ejecutivas hasta su aprobación por el Juez de Vigilancia.»","Art. 253.2 RP: «la Comisión Disciplinaria podrá acordar la ejecución inmediata de las sanciones de aislamiento en celda, cuya duración acumulada no supere los catorce días, siempre que concurran los requisitos establecidos en el apartado 2 del artículo anterior y sin perjuicio de que todas las sanciones impuestas deban ser aprobadas por el Juez de Vigilancia.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c15-regimen-disciplinario'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
