insert into public.topics (slug, title) values ('iipp-c16-juez-vigilancia', 'Derecho Penitenciario, tema 16. El Juez de Vigilancia Penitenciaria') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c16-juez-vigilancia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Juez de Vigilancia Penitenciaria (art. 76 LOGP)"},{"n":"2","title":"Atribuciones del JVP (art. 76.2 LOGP)"},{"n":"3","title":"Propuestas del JVP (art. 77 LOGP)"},{"n":"4","title":"Organización (art. 94 LOPJ) y régimen de recursos (DA 5.ª LOPJ)"}]'::jsonb, '["Art. setenta y seis.Uno LOGP: «salvaguardar los derechos de los internos y corregir los abusos y desviaciones que en el cumplimiento de los preceptos del régimen penitenciario puedan producirse.»","Art. setenta y seis.Dos.b LOGP: «Resolver sobre las propuestas de libertad condicional de los penados y acordar las revocaciones que procedan.»","Art. setenta y seis.Dos.d LOGP: «Aprobar las sanciones de aislamiento en celda de duración superior a catorce días.»","Art. setenta y seis.Dos.e LOGP: «Resolver por vía de recurso las reclamaciones que formulen los internos sobre sanciones disciplinarias.»","Art. setenta y seis.Dos.i LOGP: «Autorizar los permisos de salida cuya duración sea superior a dos días, excepto de los clasificados en tercer grado.»","Art. setenta y seis.Dos.c LOGP: «Aprobar las propuestas que formulen los establecimientos sobre beneficios penitenciarios que puedan suponer acortamiento de la condena.»","Art. setenta y seis.Dos.f LOGP: «Resolver en base a los estudios de los Equipos de Observación y de Tratamiento, y en su caso de la Central de Observación, los recursos referentes a la clasificación inicial y a progresiones y regresiones de grado.»","Art. setenta y seis.Dos.g LOGP: «Acordar lo que proceda sobre las peticiones o quejas que los internos formulen en relación con el régimen y el tratamiento penitenciario en cuanto afecte a lo derechos fundamentales o a los derechos y beneficio penitenciarios de aquéllos.»","Art. setenta y seis.Dos.j LOGP: «Conocer del paso a los establecimientos de régimen cerrado de los reclusos a propuesta del Director del establecimiento.»","Art. setenta y siete LOGP: «Los Jueces de Vigilancia podrán dirigirse a la Dirección General de Instituciones Penitenciarias, formulando propuestas referentes a la organización y desarrollo de los servicios de vigilancia»","Art. setenta y ocho.Dos LOGP: «Los Jueces de Vigilancia tendrán su residencia en el territorio en que radiquen los establecimientos penitenciarios sometidos a su jurisdicción.»","Art. 92.1 LOPJ: «Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, dentro del orden jurisdiccional penal, existirá una Sección de Vigilancia Penitenciaria»","Art. 92.1 LOPJ: «control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias, amparo de los derechos y beneficios de los internos en los establecimientos penitenciarios»","DA 5.ª.1 LOPJ: «El recurso de reforma podrá interponerse contra todos los autos del Juez de Vigilancia Penitenciaria.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708', null, null, null, 'Otras normas citadas: LOPJ (https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666)'
  from public.topics t where t.slug = 'iipp-c16-juez-vigilancia'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
