insert into public.topics (slug, title) values ('iipp-c17-modelo-organizativo', 'Derecho Penitenciario, tema 17. El modelo organizativo: órganos colegiados y unipersonales') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c17-modelo-organizativo' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Órganos colegiados: Consejo de Dirección, Junta de Tratamiento, Comisión Disciplinaria, Junta Económico-Administrativa (arts. 265-279 RP)"},{"n":"2","title":"Equipos técnicos (arts. 274-275 RP)"},{"n":"3","title":"Órganos unipersonales: Director, Subdirectores y Administrador (arts. 280-283 RP)"}]'::jsonb, '["Art. 265.1 RP: «En cada Establecimiento penitenciario existirán los siguientes órganos colegiados: a) Consejo de Dirección. b) Junta de Tratamiento, que tendrá a su disposición, como unidades de estudio, propuesta y ejecución, el Equipo o Equipos Técnicos necesarios. c) Comisión Disciplinaria. d) Junta Económico-Administrativa.»","Art. 265.2 RP: «Las funciones de coordinación entre los diferentes órganos colegiados corresponden al Director del Establecimiento.»","Art. 265.4 RP: «En los Hospitales psiquiátricos penitenciarios sólo existirán el Consejo de Dirección, cuya composición se determinará por las normas de desarrollo de este Reglamento, la Junta Económico-Administrativa y los Equipos multidisciplinares necesarios.»","Art. 266.1 RP: «La eficacia de los acuerdos de los órganos colegiados del Establecimiento, con la excepción de los adoptados por la Comisión Disciplinaria, quedará demorada hasta que se produzca la aprobación por el Director del Centro.»","Art. 266.2 RP: «Los acuerdos de los órganos colegiados que hayan sido confirmados total o parcialmente por el Juez de Vigilancia Penitenciaria, directamente o en vía de recurso, no podrán demorar su eficacia, ni ser revocados o anulados por decisión administrativa.»","Art. 267.3 RP: «Los miembros de los órganos colegiados de los Establecimientos penitenciarios no podrán abstenerse en las votaciones, aunque podrán formular votos particulares que se incorporarán al acuerdo adoptado.»","Art. 267.4 RP: «Los votos del Presidente, que serán dirimentes en caso de empate»","Art. 268.3 RP: «La Comisión Disciplinaria se reunirá en sesión ordinaria cuatro veces al mes»","Art. 268.4 RP: «La Junta Económico-Administrativa se reunirá en sesión ordinaria una vez al trimestre»","Art. 268.6 RP: «Cuando no se alcance el quórum exigido, el Presidente efectuará una nueva convocatoria en el plazo de cuarenta y ocho horas.»","Art. 269.1 RP: «El sustituto del Director en la presidencia de la Junta Económico-Administrativa será el Administrador del centro penitenciario.»","Art. 270.1 RP: «a) El Subdirector de Régimen. b) El Subdirector de Seguridad. c) El Subdirector de Tratamiento. d) El Subdirector Médico o Jefe de los Servicios Médicos. e) El Subdirector de Personal, si lo hubiere. f) El Administrador.»","Art. 271.1.b RP: «Elaborar las normas de régimen interior del Centro penitenciario para su aprobación por el Centro Directivo.»","Art. 271.1.f RP: «Fijar los días en que puedan comunicar los internos y establecer los horarios de las comunicaciones especiales y de recepción y recogida de paquetes y encargos, así como de los recuentos ordinarios.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c17-modelo-organizativo'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
