insert into public.topics (slug, title) values ('iipp-c18-oficina-gestion-expediente', 'Derecho Penitenciario, tema 18. Régimen administrativo (1): oficina de gestión, expediente personal y liquidación de condena') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c18-oficina-gestion-expediente' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La oficina de gestión (RP 1981)"},{"n":"2","title":"El expediente personal del interno"},{"n":"3","title":"Liquidación de condena y abono de la prisión preventiva (arts. 58-59 CP)"}]'::jsonb, '["Art. 334 RP 1981: «Oficina de Régimen, en la que se formalizará cuanto se refiere a la población interna: expedientes personales y de libertad condicional, libros, fichas y estadística.»","Art. 334 RP 1981: «Oficina de Dirección, en la que se tramitará todo lo referente a funcionarios, sus expedientes personales y documentación, comunicación con las Autoridades, órdenes en general y libros de servicio.»","Art. 334 RP 1981: «Oficina de Servicio Interior, en la que se redactarán y cursarán los partes reglamentarios al Director»","Art. 335 RP 1981: «El Libro de Servicios, que recogerá de forma precisa todos los del establecimiento y los funcionarios a quienes se les asignan»","Art. 336 RP 1981: «Si un individuo ingresara de nuevo no se le abrirá otro expediente, sino que ha de continuarse el que tuviere»","Art. 336 RP 1981: «Toda anotación irá autorizada con la firma del funcionario de la oficina, la del Jurista-Criminólogo, cuando corresponda, la del Subdirector y el visto bueno del Director.»","Art. 336 RP 1981: «El libro de ingresos y filiaciones, ajustado al modelo oficial.»","Art. 336 RP 1981: «La Estadística general clasificada de los internos existentes a las veinticuatro horas del día último de cada mes, que se remitirá al Centro Directivo del día 1 del siguiente.»","Art. 336 RP 1981: «Las agendas para anotación de fechas de licenciamientos definitivos; cumplimientos de la primera, tercera y cuarta parte de la totalidad de las condenas; revisiones de clasificación»","Art. 336 RP 1981: «las certificaciones, la firma del Subdirector como responsable del servicio y el visto bueno del Director.»","Art. 337 RP 1981: «constarán de tres partes, que se diligenciarán, respectivamente, en las fases de detención, cumplimiento y reinserción social»","Art. 337 RP 1981: «El protocolo de cada observado se unirá, con carácter de reservado y en sobre cerrado, al expediente que acompañará al mismo cuando sea trasladado a otro establecimiento.»","Art. 340 RP 1981: «La impresión dactilar del pulgar derecho en el expediente del interno a su ingreso y salida, cualquiera que sea el motivo.»","Art. 340 RP 1981: «La remisión al Centro Directivo, del 1 al 10 de cada mes, de todo lo realizado en el anterior o comunicación negativa, caso de no haber ingresos»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095', null, null, null, null
  from public.topics t where t.slug = 'iipp-c18-oficina-gestion-expediente'
