insert into public.topics (slug, title) values ('iipp-c19-oficina-servicio-interior', 'Derecho Penitenciario, tema 19. Régimen administrativo (2): oficina de servicio interior, partes, rastrillo, comunicaciones, ingresos y paquetes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c19-oficina-servicio-interior' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La oficina de servicio interior y los Jefes de Centro (RP 1981, art. 303)"},{"n":"2","title":"Unidades de acceso, rastrillo, patios y galerías (arts. 305-310)"},{"n":"3","title":"Partes de servicio y comunicaciones (arts. 317-323)"},{"n":"4","title":"Ingresos y paquetes"}]'::jsonb, '["Art. 339 RP 1981: «Los partes de recuento de la población interna, en los que se recogerán los parciales presentados por los funcionarios de los distintos departamentos.»","Art. 339 RP 1981: «a) El de incidencias, en que harán constar las que por su interés aconsejen su anotación.»","Art. 339 RP 1981: «El de órdenes de la Dirección, donde se transcribirán íntegramente las que se reciban.»","Art. 303 RP 1981: «Controlar los desplazamientos de internos de unas dependencias a otras, cuidando que se mantenga adecuadamente la clasificación interior.»","Art. 305 RP 1981: «Serán consideradas unidades de acceso la puerta principal y cualquier otra entrada de personas o vehículos al interior del establecimiento.»","Art. 305 RP 1981: «recoger la documentación de quienes sean ajenos al mismo, conservándola en su poder hasta la salida.»","Art. 305 RP 1981: «Controlar las entradas y salidas de vehículos, anotando la matrícula y la identidad del conductor, y comprobar su contenido.»","Art. 307 RP 1981: «Por la noche no abrirá sin previo conocimiento y autorización del Jefe de Servicios.»","Art. 307 RP 1981: «Impedir, cuando se trate de rastrillos interiores, el paso de los internos, salvo cuando exista orden escrita superior, exigiendo la firma del funcionario que se haga cargo de los mismos.»","Art. 307 RP 1981: «Las Unidades de servicio de rastrillo estarán integradas por uno o dos de éstos cuando se hallen en proximidad inmediata, y por los locales o dependencias anejos, constituyendo un punto de paso.»","Art. 308 RP 1981: «Controlar a los internos que permanezcan en el mismo, conociendo en todo momento su contingente.»","Art. 309 RP 1981: «Comunicar al superior inmediato, mediante el correspondiente parte por escrito, cualquier incidencia o irregularidad ocurrida»","Art. 310 RP 1981: «Conservar en su poder las llaves correspondientes, practicando personalmente las operaciones de apertura y cierre de puertas.»","Art. 312 RP 1981: «Impedir que se extraigan medicamentos, comidas, ropas u otros efectos, o que sean facilitados a los enfermos sin autorización del facultativo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095', null, null, null, null
  from public.topics t where t.slug = 'iipp-c19-oficina-servicio-interior'
