insert into public.topics (slug, title) values ('iipp-c20-regimen-economico-peculio', 'Derecho Penitenciario, tema 20. Régimen económico: peculio, pertenencias, economato, almacenes y habilitación') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c20-regimen-economico-peculio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Régimen económico de los establecimientos (arts. 293-310 RP)"},{"n":"2","title":"Peculio de los internos"},{"n":"3","title":"Pertenencias y depósito de objetos"},{"n":"4","title":"Economato, almacenes y habilitación (arts. 300-324 RP)"}]'::jsonb, '["Art. 293.1 RP: «Los Servicios administrativos de los Establecimientos penitenciarios dependen directamente del Administrador del centro.»","Art. 293.2 RP: «Todo acto o decisión económico-administrativa de un Establecimiento penitenciario deberá estar propuesto por el Administrador y autorizado por el Director del centro»","Art. 294.1 RP: «exigiéndose, en todo caso, la firma mancomunada del Director y del Administrador del Establecimiento o, en su caso, del suplente de uno u otro.»","Art. 298 RP: «Los economatos de los Establecimientos penitenciarios son un servicio prestado por la institución penitenciaria a los internos que permite disponer de un sistema de adquisición de productos de naturaleza complementaria»","Art. 300.1 RP: «a) La propia Administración penitenciaria. b) El Organismo Autónomo Trabajo y Prestaciones Penitenciarias, mediante la fórmula de taller productivo. c) Empresas externas adjudicatarias por contrato administrativo de servicios.»","Art. 301.1 RP: «Queda prohibido a los internos el uso de dinero de curso legal, salvo en los Establecimientos de régimen abierto o en situaciones excepcionales debidamente autorizadas por el centro directivo.»","Art. 303.2 RP: «En ningún caso podrán venderse en el economato ningún tipo de bebidas alcohólicas ni de productos farmacéuticos.»","Art. 305.1 RP: «las prestaciones que deban realizar los internos en servicios auxiliares o mecánicos de los mismos no tendrán, en ningún caso, la naturaleza de relación laboral especial penitenciaria»","Art. 305.2 RP: «los servicios auxiliares o mecánicos de los mismos desempeñados por los internos tendrán la naturaleza de relación laboral especial penitenciaria.»","Art. 311 RP: «Si algún interno renunciase a su ración, quedará ésta en beneficio de los demás, no de persona determinada, sin que por tal renuncia se le deba indemnización alguna.»","Art. 313.1 RP: «La composición del vestuario se determinará por resolución del centro directivo correspondiente»","Art. 316.1 RP: «Los Establecimientos penitenciarios solicitarán mensualmente, en función de la previsión de población interna existente y de sus características personales y penitenciarias, las necesidades de dotación en lotes higiénicos.»","Art. 317 RP: «Los objetos de valor se custodiarán por el Subdirector de Seguridad en la caja del Establecimiento o en lugar seguro y el dinero será custodiado por el Administrador.»","Art. 317 RP: «Salvo en los Establecimientos de régimen abierto, los internos no tendrán en su poder dinero o títulos que lo representen ni objetos de valor.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c20-regimen-economico-peculio'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
